iterations.rule_text:
{
 "title": "Suspicious AdFind Enumeration",
 "description": "Detects execution of AdFind.exe with command-line switches associated with Active Directory enumeration and reconnaissance.",
 "tags": [
  "attack.discovery",
  "attack.t1087.002"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "selection_image",
   "fields": [
    {
     "field": "Image",
     "modifier": "endswith",
     "values": [
      "\\adfind.exe"
     ]
    },
    {
     "field": "OriginalFileName",
     "modifier": "exact",
     "values": [
      "AdFind.exe"
     ]
    }
   ]
  },
  {
   "name": "selection_cmdline",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "-kdsrootkeys",
      "-csvbreakcount",
      "-onlygroup",
      "-whoami",
      "-decattid",
      "-enccurrentutcgt",
      "-encutcgt",
      "-outputcurrentint8",
      "-outputcurrentgt",
      "-jwdsinit",
      "-jwdsstd",
      "-jwdsstdro",
      "parentrdn",
      "objrdn",
      "-dechextosid",
      "-encguidtoiid",
      "(objectcategory="
     ]
    }
   ]
  },
  {
   "name": "filter_falsepositive",
   "fields": []
  }
 ],
 "condition": "selection_image and selection_cmdline and not filter_falsepositive",
 "falsepositives": [
  "Legitimate administrative use of AdFind for authorized AD queries."
 ],
 "level": "high"
}

